<span class="line"><span style="color:#ABB2BF;">x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">arange</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">-</span><span style="color:#D19A66;">8.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">8.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0.1</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">requires_grad</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">True</span><span style="color:#ABB2BF;">)</span></span>
